insert into segments (module_id, segment_code, title, script_text,
  tones, tone_map, condition, script_note, section, sort_order,
  coaching, client_should_feel, verbatim, status) values
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La presentación$vn$), $vn$BOLTES-002$vn$, $vn$Phase One$vn$, $vn$La Fase 1 comienza inmediatamente cuando te inscribes y continúa hasta que te gradúas. Van a trabajar contigo para restaurar tus ahorros mensuales con una sólida educación financiera. Van a configurar monitoreo mensual de crédito para seguir tu progreso. Y te van a poner en contacto con un bufete de abogados que se asegurará de proteger tus derechos como consumidor. La mayor parte del trabajo en esta fase es preparar la base para resolver la deuda y mejorar el crédito en la Fase 2. ¿Tiene sentido hasta ahora?$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "La Fase 1 comienza inmediatamente cuando te inscribes y continúa hasta que te gradúas. Van a trabajar contigo para restaurar tus ahorros mensuales con una sólida educación financiera. Van a configurar monitoreo mensual de crédito para seguir tu progreso. Y te van a poner en contacto con un bufete de abogados que se asegurará de proteger tus derechos como consumidor. La mayor parte del trabajo en esta fase es preparar la base para resolver la deuda y mejorar el crédito en la Fase 2. ¿Tiene sentido hasta ahora?"}]$vn$::jsonb, null, null, $vn$La compañía y la Fase 1$vn$, 20, $vn$Steady pace through the list. Do not rush it into one breath. Soften on the check-in question at the end.$vn$, $vn$Something starts happening for me right away.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La presentación$vn$), $vn$BOLTES-003$vn$, $vn$Phase Two Setup$vn$, $vn$La Fase 2 comienza cuando las cuentas pasan a cobranzas. Ahora quiero ser muy claro aquí... … tus cuentas NO necesitan estar en cobranzas para inscribirte. De hecho, la mayoría de las personas como tú se inscriben antes de que las cuentas estén con una agencia de cobranza. ¿Tiene sentido?$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "La Fase 2 comienza cuando las cuentas pasan a cobranzas. Ahora quiero ser muy claro aquí... … tus cuentas NO necesitan estar en cobranzas para inscribirte. De hecho, la mayoría de las personas como tú se inscriben antes de que las cuentas estén con una agencia de cobranza. ¿Tiene sentido?"}]$vn$::jsonb, null, null, $vn$La Fase 2$vn$, 30, $vn$Real pause before the clarification. Slow down and weight "do not need to be" — this is the sentence that prevents a cancellation three months from now.$vn$, $vn$I am not behind, and I am not disqualified.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La presentación$vn$), $vn$BOLTES-004$vn$, $vn$How The Accounts Move$vn$, $vn$Entonces, el primer paso de esta fase es mostrarles a los acreedores que estás pasando por una dificultad, de la única manera que ellos entienden, permitiendo que las cuentas se cierren y se atrasen. Al dejar de hacer los pagos mínimos mensuales, las cuentas inscritas se atrasarán y eventualmente pasarán a cobranzas.$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "Entonces, el primer paso de esta fase es mostrarles a los acreedores que estás pasando por una dificultad, de la única manera que ellos entienden, permitiendo que las cuentas se cierren y se atrasen. Al dejar de hacer los pagos mínimos mensuales, las cuentas inscritas se atrasarán y eventualmente pasarán a cobranzas."}]$vn$::jsonb, null, null, $vn$La Fase 2$vn$, 40, $vn$Do not soften this and do not speed up through it. Say it at the same pace as everything else. Speeding up here is what reps do when they are uncomfortable, and the client hears it.$vn$, $vn$He told me the hard part without dressing it up.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La presentación$vn$), $vn$BOLTES-005$vn$, $vn$The Dispute$vn$, $vn$Ahora, una vez que tus cuentas estén en cobranzas, entramos nosotros y disputamos el derecho del cobrador de deudas a siquiera cobrar tus cuentas. Por ley, estos cobradores de deudas deben proporcionar prueba de que tienen el derecho legal de cobrar tus deudas. También deben demostrar y verificar que han cumplido con la ley con respecto a tu deuda y cómo se está reportando en tu crédito, y aquí es donde está el problema. ¿Ves lo que te estoy diciendo?$vn$, array[$vn$AC$vn$,$vn$RM$vn$]::text[], $vn$[{"tone": "AC", "text": "Ahora, una vez que tus cuentas estén en cobranzas, entramos nosotros y disputamos el derecho del cobrador de deudas a siquiera cobrar tus cuentas. Por ley, estos cobradores de deudas deben proporcionar prueba de que tienen el derecho legal de cobrar tus deudas. También deben demostrar y verificar que han cumplido con la ley con respecto a tu deuda y cómo se está reportando en tu crédito, y aquí es donde está el problema."}, {"tone": "RM", "text": "¿Ves lo que te estoy diciendo?"}]$vn$::jsonb, null, null, $vn$La Fase 2$vn$, 50, $vn$Build slightly through the legal requirements. Land on "this is where the problem lies" and let it sit before the check-in.$vn$, $vn$There is a real legal mechanism here, not a gimmick.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La presentación$vn$), $vn$BOLTES-006$vn$, $vn$Uncollectable$vn$, $vn$Ahora, cuando no pueden proporcionar prueba legal de que tienen derecho a cobrar tu cuenta, esa cuenta se convierte en lo que se llama “incobrable”, lo que significa que el cobrador externo ya no puede intentar cobrarte esa deuda. Bolton Services Group no paga tus cuentas; más bien, hace valer tu derecho legal a disputar la deuda. ¿Sigues conmigo?$vn$, array[$vn$AC$vn$,$vn$PT$vn$,$vn$RM$vn$]::text[], $vn$[{"tone": "AC", "text": "Ahora, cuando no pueden proporcionar prueba legal de que tienen derecho a cobrar tu cuenta, esa cuenta se convierte en lo que se llama “incobrable”,"}, {"tone": "PT", "text": "lo que significa que el cobrador externo ya no puede intentar cobrarte esa deuda."}, {"tone": "AC", "text": "Bolton Services Group no paga tus cuentas; más bien, hace valer tu derecho legal a disputar la deuda."}, {"tone": "RM", "text": "¿Sigues conmigo?"}]$vn$::jsonb, null, null, $vn$La Fase 2$vn$, 60, $vn$Flatten into Plain Talk on the definition of uncollectable. The line about not paying off accounts must be said clearly and without hedging.$vn$, $vn$I understand exactly what they do and do not do.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La presentación$vn$), $vn$BOLTES-007$vn$, $vn$Recap The Process$vn$, $vn$Tomemos un momento para repasar el proceso. La meta principal es resolver la deuda. Hacemos esto disputando las cuentas con los cobradores de deudas una vez que las cuentas son dadas de baja por los acreedores originales, porque es la manera más rápida y menos costosa de resolver la deuda. Ahora, FIRST NAME, ¿qué crees que pasaría si la deuda fuera declarada incobrable y ya no pudiera afectar tu puntaje de crédito?$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "Tomemos un momento para repasar el proceso. La meta principal es resolver la deuda. Hacemos esto disputando las cuentas con los cobradores de deudas una vez que las cuentas son dadas de baja por los acreedores originales, porque es la manera más rápida y menos costosa de resolver la deuda. Ahora, FIRST NAME, ¿qué crees que pasaría si la deuda fuera declarada incobrable y ya no pudiera afectar tu puntaje de crédito?"}]$vn$::jsonb, null, null, $vn$Repaso de las metas$vn$, 70, $vn$The question at the end is the point of the whole recap. Use their name, ask it, then stop completely and let them answer it themselves.$vn$, $vn$I just said the benefit out loud in my own words.$vn$, false, 'published');
